db.sessions.createIndex({ createdAt: 1 }, { expireAfterSeconds: 3600 });    // TTL
// Aggregation: actions per user in last 30 days
db.audit_logs.aggregate([
{ $match: { at: { $gte: new Date(Date.now() - 30*24*3600*1000) } } },
{ $group: { _id: "$user", actions: { $sum: 1 } } },
{ $sort: { actions: -1 } },
{ $limit: 10 }
]);
// $lookup = left outer join
db.loans.aggregate([{ $lookup: { from: "members", localField: "memberId", foreignField: "_id", as: "member" } },
{ $unwind: "$member" }]);
