// Map Keycloak realm roles (realm_access.roles) to Spring authorities
@Bean
JwtAuthenticationConverter keycloakConverter() {
JwtAuthenticationConverter conv = new JwtAuthenticationConverter();
conv.setJwtGrantedAuthoritiesConverter(jwt -> {
Map<String, Object> realm = jwt.getClaim("realm_access");
if (realm == null) return List.of();
@SuppressWarnings("unchecked")
List<String> roles = (List<String>) realm.getOrDefault("roles", List.of());
return roles.stream().map(r -> new SimpleGrantedAuthority("ROLE_" + r)).collect(Collectors.toList());
});
return conv;
}
